/* ---------- Bar chart ---------- */
/* agent runs a day: one bar each in the accent, with no legend, and each bar's breakdown in its hover readout. The readout
   is the page's tooltip (opaque and neutral) beside the bar it reads, level with its top, on the side with room and always
   inside the chart (the script places it, and it follows the bar as it grows). The content sits 16px in from every edge */
.bcx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.bcx-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.bcx-h>div:first-child{display:flex;flex-direction:column;font-size:12.5px;line-height:18px}
.bcx-v{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.02em}
.bcx-rg button{font-size:12px;height:26px;padding:0 10px}
.bcx-ch{display:flex;align-items:flex-end;gap:var(--dm-s-2);height:150px;position:relative}
.bcx-b{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;gap:0;position:relative;cursor:default}
.bcx-st{display:flex;flex-direction:column-reverse;gap:2px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));overflow:hidden;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.bcx-st i{display:block;height:0;transition:height .7s var(--dm-ease)}
.bcx-st i:nth-child(1){background:var(--dm-c1)}
@media (hover:hover) and (pointer:fine){.bcx-ch:hover .bcx-b:not(:hover) .bcx-st{opacity:.4}}
.bcx-l{font-size:11px;line-height:14px;color:var(--dm-muted);text-align:center;margin-top:6px;height:14px}
.bcx-tt{position:absolute;left:0;bottom:calc(100% + 6px);z-index:2;padding:6px 9px;border-radius:var(--dm-r-sm);background:var(--dm-tip-bg,var(--dm-ink));color:var(--dm-tip-fg,var(--dm-on-ink));box-shadow:var(--dm-tip-ring,none);font-size:12px;line-height:1.35;white-space:nowrap;opacity:0;pointer-events:none;transform:translateY(4px);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease);display:flex;flex-direction:column}
.bcx-tt b{font-weight:500}
.bcx-tt span{color:color-mix(in srgb,var(--dm-tip-fg,var(--dm-on-ink)) 76%,var(--dm-tip-bg,var(--dm-ink)))}
@media (hover:hover) and (pointer:fine){.bcx-b:hover .bcx-tt{opacity:1;transform:none}}
.bcx-lg{display:flex;gap:14px;font-size:12px;flex-wrap:wrap}
.bcx-lg span{display:flex;align-items:center;gap:6px}
.bcx-lg i{width:8px;height:8px;border-radius:var(--dm-r-tiny,3px)}
/* Clean: the bars stand on a hairline baseline (half strength) with their tops rounded, as a bar chart is usually drawn */
:root[data-style="clean"] .bcx-st,:root [data-style="clean"] .bcx-st,:root [data-style="clean"].bcx-st{border-radius:calc(6px * var(--dm-rk-m,var(--dm-rk))) calc(6px * var(--dm-rk-m,var(--dm-rk))) 2px 2px}
:root[data-style="clean"] .bcx-ch,:root [data-style="clean"] .bcx-ch,:root [data-style="clean"].bcx-ch{background:linear-gradient(color-mix(in srgb,var(--dm-line) 50%,transparent),color-mix(in srgb,var(--dm-line) 50%,transparent)) left 0 bottom 20px/100% 1px no-repeat}

DM.def('bar-chart', (r, c) => {
  const D = {
    w:{ l:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], d:[[42,9,2],[51,12,3],[48,8,1],[63,10,4],[57,14,2],[18,3,0],[12,2,1]] },
    m:{ l:['W1','W2','W3','W4','W5','W6','W7'], d:[[180,40,9],[210,44,12],[236,51,8],[262,48,10],[251,39,6],[298,52,7],[321,47,5]] }
  };
  const ch = $('.bcx-ch', r), v = $('.bcx-v', r); let tot = 0;
  ch.innerHTML = D.w.l.map(() => `<div class="bcx-b"><div class="bcx-tt"></div><div class="bcx-st"><i></i></div><div class="bcx-l"></div></div>`).join('');
  const bars = $$('.bcx-b', ch);
  function draw(k){
    const d = D[k], mx = Math.max(...d.d.map(x => x[0] + x[1] + x[2])) * 1.08, H = ch.clientHeight - 22;
    bars.forEach((b, i) => { const x = d.d[i], s = x[0] + x[1] + x[2];
      c.later(i * 45, () => { $('.bcx-st i', b).style.height = Math.max(s ? 3 : 0, s / mx * H) + 'px'; });
      $('.bcx-l', b).textContent = d.l[i];
      // the readout: the bar's total, then each part on a line of its own, so it stays narrow enough to sit beside its bar
      $('.bcx-tt', b).innerHTML = `<b class="num">${s} runs</b><span class="num">${x[0]} shipped</span><span class="num">${x[1]} reviewed</span><span class="num">${x[2]} failed</span>`; });
    const t = d.d.reduce((a, x) => a + x[0] + x[1] + x[2], 0); tween(tot, t, 900, n => { tot = n; v.textContent = Math.round(n).toLocaleString('en-US'); });
  }
  // a bar's readout sits beside it, level with its top: on its right while it fits there, then on its left, and always inside
  // the chart (on a narrow one it may cover part of its own bar), over the bars and clear of the labels under them
  const place = b => { const tt = $('.bcx-tt', b), st = $('.bcx-st', b), H = ch.clientHeight, w = tt.offsetWidth, h = tt.offsetHeight, bl = b.offsetLeft, bw = b.offsetWidth, base = H - st.offsetTop - st.offsetHeight;
    tt.style.bottom = Math.max(base, Math.min(H - h, base + st.offsetHeight - h)) + 'px'; tt.style.left = Math.max(-bl, Math.min(ch.clientWidth - bl - w, bl + bw + 6 + w <= ch.clientWidth ? bw + 6 : -w - 6)) + 'px'; };
  // it follows its bar while the bar grows or the range changes under the pointer
  let hot = null;
  const follow = () => { if (!hot || c.dead) return; place(hot); requestAnimationFrame(follow); };
  bars.forEach(b => { c.on(b, 'pointerenter', () => { const was = hot; hot = b; if (!was) follow(); }); c.on(b, 'pointerleave', () => { if (hot === b) hot = null; }); });
  seg($('.bcx-rg', r), draw);
  c.later(280, () => draw('w'));
});
